static int afs_dynroot_readdir_cells(struct afs_net *net, struct dir_context *ctx)
{
	const struct afs_cell *cell;
	loff_t newpos;
	char buf[AFS_MAXCELLNAME + 2];

	_enter("%llu", ctx->pos);

	for (;;) {
		unsigned int ix = ctx->pos >> 1;
		unsigned int name_len;
		unsigned int dynroot_ino;

		rcu_read_lock();
		cell = idr_get_next(&net->cells_dyn_ino, &ix);
		if (!cell) {
			rcu_read_unlock();
			return 0;
		}
		if (READ_ONCE(cell->state) == AFS_CELL_REMOVING ||
		    READ_ONCE(cell->state) == AFS_CELL_DEAD) {
			rcu_read_unlock();
			ctx->pos += 2;
			ctx->pos &= ~1;
			continue;
		}

		newpos = ix << 1;
		if (newpos > ctx->pos)
			ctx->pos = newpos;

		_debug("pos %llu -> cell %u", ctx->pos, cell->dynroot_ino);

		name_len = cell->name_len;
		dynroot_ino = cell->dynroot_ino;
		if (name_len > AFS_MAXCELLNAME)
			name_len = AFS_MAXCELLNAME;
		memcpy(buf, cell->name - 1, name_len + 2);

		rcu_read_unlock();

		if ((ctx->pos & 1) == 0) {
			if (!dir_emit(ctx, buf + 1, name_len,
				      dynroot_ino, DT_DIR))
				return 0;
			ctx->pos++;
		}
		if ((ctx->pos & 1) == 1) {
			if (!dir_emit(ctx, buf, name_len + 1,
				      dynroot_ino + 1, DT_DIR))
				return 0;
			ctx->pos++;
		}
	}
	return 0;
}

